edits.replacement:
// v16.xx, seen on the lift screenshot (2026-10-07): each sector card is as tall as its map, and the name and facts were
// 16 and 13 pixel lines across the top of it, a big empty card. The name is a heading now and the lines under it read
// at a glance; the words are his, untouched.
'<div><b style="font-size:28px;letter-spacing:.04em;line-height:1.15;color:'+(sel?'var(--amber)':'var(--bone)')+'">'+M.name+'</b>'+
' <span style="color:var(--ash);font-size:14px;letter-spacing:.08em">'+sizeTag(i)+'</span>'+
(sel?' <span style="color:var(--amber);font-size:14px;letter-spacing:.08em">ASCENDING HERE</span>':'')+
'<div class="hint" style="margin:10px 0 0;font-size:17px;line-height:1.5">'+SECTOR_CHAR[i]+'</div>'+
'<div class="hint" style="margin:8px 0 0;font-size:16px;line-height:1.6;color:var(--ash)">'+facts.join('  &middot;  ')+'</div></div></div>';

check:
{v:'VER',what:'the sector cards read at a glance: on the lift page the sector name is a heading of 24 pixels or more and its facts line 15 or more',
 run:function(){
   if(typeof __station!=='function'||typeof __hubEnter!=='function') return 'SKIP: no stations here';
   var bad=[], t, row, b, hs, f;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     t=document.getElementById('title'); if(t) t.classList.remove('on');
     __hubEnter(); __station('lift','KeyE');
     row=document.querySelector('.modal.on .sectorpick');
     if(!row) return 'SKIP: the lift page drew no sector card';
     b=row.querySelector('b'); hs=row.querySelectorAll('.hint');
     if(!b||hs.length<2) return 'SKIP: the sector card has another shape';
     f=parseFloat(getComputedStyle(b).fontSize); if(!(f>=24)) bad.push('the sector name is '+f+'px');
     f=parseFloat(getComputedStyle(hs[hs.length-1]).fontSize); if(!(f>=15)) bad.push('the facts line is '+f+'px');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
